-- Rollback-only metadata/fact publication contract; this does not prove HTTP Storage bytes.
begin;
create function pg_temp.pp_id(n integer) returns uuid language sql immutable as $$select ('f9300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.pp_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.pp_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected SQLSTATE %',state;end$$;
create function pg_temp.pp_player(home boolean,n integer) returns jsonb language sql as $$select jsonb_build_object('jerseyNumber',case when n=0 then '0' when n=1 then '00' else n::text end,'name','Fixture Player '||n,'starter',false,'captain',false,'didNotPlay',false,'secondsPlayed',300,'fieldGoals',jsonb_build_object('made',case when home and n=0 then 1 else 0 end,'attempted',case when home and n=0 then 1 else 0 end),'twoPoints',jsonb_build_object('made',case when home and n=0 then 1 else 0 end,'attempted',case when home and n=0 then 1 else 0 end),'threePoints',jsonb_build_object('made',0,'attempted',0),'freeThrows',jsonb_build_object('made',0,'attempted',0),'offensiveRebounds',0,'defensiveRebounds',0,'rebounds',0,'assists',0,'turnovers',0,'steals',0,'blocks',0,'foulsCommitted',0,'foulsReceived',null,'plusMinus',null,'efficiency',case when home and n=0 then 2 else 0 end,'points',case when home and n=0 then 2 else 0 end)$$;
create function pg_temp.pp_parsed() returns jsonb language sql as $$select jsonb_build_object('format','BASKETBALL_SITE','parserVersion','basketball-site-v1','competitionName',null,'gameNumber',null,'scheduledLocal','2026-10-24T10:00','durationSeconds',null,'venue','Fixture','warnings','[]'::jsonb,'teams',(select jsonb_agg(jsonb_build_object('name',case when side=0 then 'Home' else 'Away' end,'abbreviation','','score',case when side=0 then 2 else 0 end,'periodScores',null,'players',(select jsonb_agg(pg_temp.pp_player(side=0,n) order by n) from generate_series(0,4) n)) order by side) from generate_series(0,1) side))$$;
create function pg_temp.pp_review() returns jsonb language sql as $$select jsonb_build_object('disputeId',pg_temp.pp_id(3),'gameId',pg_temp.pp_id(8),'invertSides',false,'notes','','mappings',(select jsonb_agg(jsonb_build_object('sourceSide',side,'sourceIndex',n,'rosterEntryId',pg_temp.pp_id(101+side*5+n),'jersey',case when n=0 then '0' when n=1 then '00' else n::text end) order by side,n) from generate_series(0,1) side cross join generate_series(0,4) n))$$;
create function pg_temp.pp_command(n integer default 1) returns jsonb language sql as $$select jsonb_build_object('requestId',pg_temp.pp_id(500+n),'gameId',pg_temp.pp_id(8),'gameVersion',1,'basePublicationVersion',0,'source',jsonb_build_object('kind','pdf','sourceId',pg_temp.pp_id(100),'sourceVersion',2,'reviewVersion',1),'supplement',jsonb_build_object('rows',(select jsonb_agg(jsonb_build_object('sourceSide',side,'sourceIndex',i,'played',true,'starter',true,'captain',i=0) order by side,i) from generate_series(0,1) side cross join generate_series(0,4) i),'staff',jsonb_build_object('home',jsonb_build_object('coachStaffEntryId',null,'assistantStaffEntryId',null),'away',jsonb_build_object('coachStaffEntryId',null,'assistantStaffEntryId',null))),'authority',jsonb_build_object('scorePoints','pdf','periodScores','none','playerAdvanced','pdf','foulsReceived','none','teamAdvanced','none','gameAdvanced','none'),'sheetVersion',null,'reason','','acceptDivergence',false)$$;
create function pg_temp.pp_revision(n integer default 8) returns jsonb language sql as $$select pg_temp.pp_command(n)||jsonb_build_object('gameVersion',2,'basePublicationVersion',1,'reason','Conferência e republicação do PDF.')$$;
grant execute on function pg_temp.pp_id(integer),pg_temp.pp_assert(boolean,text),pg_temp.pp_error(text,text),pg_temp.pp_player(boolean,integer),pg_temp.pp_parsed(),pg_temp.pp_review(),pg_temp.pp_command(integer),pg_temp.pp_revision(integer) to anon,authenticated,service_role;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.pp_id(98)),(pg_temp.pp_id(99));
insert into public.admin_access(user_id) values(pg_temp.pp_id(98));
insert into public.championships(id,name) values(pg_temp.pp_id(1),'PDF publication fixture');
insert into public.seasons(id,championship_id,year) values(pg_temp.pp_id(2),pg_temp.pp_id(1),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.pp_id(3),pg_temp.pp_id(2),'masculino','Adulto');
insert into public.teams(id,name) values(pg_temp.pp_id(4),'Global team');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.pp_id(5),pg_temp.pp_id(3),pg_temp.pp_id(4),'Home'),(pg_temp.pp_id(6),pg_temp.pp_id(3),pg_temp.pp_id(4),'Away');
insert into public.games(id,dispute_id,home_registration_id,away_registration_id) values(pg_temp.pp_id(8),pg_temp.pp_id(3),pg_temp.pp_id(5),pg_temp.pp_id(6)),(pg_temp.pp_id(9),pg_temp.pp_id(3),pg_temp.pp_id(5),pg_temp.pp_id(6));
insert into public.persons(id,name) select pg_temp.pp_id(200+n),'Player '||n from generate_series(1,10) n;
insert into private.athletes(person_id,sex,birth_date,federation_registration) select pg_temp.pp_id(200+n),'male','1990-01-01'::date,lpad(n::text,6,'0') from generate_series(1,10) n;
insert into public.roster_entries(id,registration_id,dispute_id,person_id,jersey) select pg_temp.pp_id(100+n),case when n<=5 then pg_temp.pp_id(5) else pg_temp.pp_id(6) end,pg_temp.pp_id(3),pg_temp.pp_id(200+n),case when (n-1)%5=0 then '0' when (n-1)%5=1 then '00' else ((n-1)%5)::text end from generate_series(1,10) n;
insert into public.pdf_sources(id,dispute_id,filename,sha256,byte_size,page_count,parsed,created_by,ready,version) values(pg_temp.pp_id(100),pg_temp.pp_id(3),'Fixture.pdf',repeat('b',64),10,1,pg_temp.pp_parsed(),pg_temp.pp_id(98),true,2);
insert into storage.objects(bucket_id,name,metadata,owner_id) values('boxscore-sources','sources/'||pg_temp.pp_id(100)::text||'.pdf','{"mimetype":"application/pdf","size":10}',pg_temp.pp_id(98)::text);
set local role authenticated;
set local request.jwt.claim.sub='f9300000-0000-4000-8000-000000000098';
select public.save_pdf_review(jsonb_build_object('commandId',pg_temp.pp_id(400),'sourceId',pg_temp.pp_id(100),'expectedVersion',0,'document',pg_temp.pp_review()));
set local role anon;
select pg_temp.pp_error('select public.publish_pdf_game(pg_temp.pp_command())','42501');
set local role authenticated;
set local request.jwt.claim.sub='f9300000-0000-4000-8000-000000000099';
select pg_temp.pp_error('select public.publish_pdf_game(pg_temp.pp_command())','PT403');
reset role;
-- Force failure after private inserts to verify full transaction rollback and command retry.
create function pg_temp.pp_fail() returns trigger language plpgsql as $$begin raise exception 'fixture PDF publication failure';end$$;
create trigger pdf_publication_fixture_failure before insert on public.published_games for each row execute function pg_temp.pp_fail();
set local role authenticated;
set local request.jwt.claim.sub='f9300000-0000-4000-8000-000000000098';
select pg_temp.pp_error('select public.publish_pdf_game(pg_temp.pp_command())','P0001');
reset role;
select pg_temp.pp_assert(not exists(select 1 from private.publication_sources where kind='pdf' and id=pg_temp.pp_id(100)) and not exists(select 1 from private.game_publication_versions where game_id=pg_temp.pp_id(8)),'failed publish keeps history and source binding empty');
drop trigger pdf_publication_fixture_failure on public.published_games;
set local role authenticated;
select pg_temp.pp_assert(public.publish_pdf_game(pg_temp.pp_command())->'version'='1','first PDF publication');
select pg_temp.pp_assert(public.publish_pdf_game(pg_temp.pp_command())->'version'='1','response-loss replay');
select pg_temp.pp_error('select public.publish_pdf_game(pg_temp.pp_command(2))','PT409');
select pg_temp.pp_error($q$select public.publish_pdf_game(jsonb_set(pg_temp.pp_command(),'{reason}','"different"'))$q$,'PT409');
select pg_temp.pp_assert(public.get_public_game(pg_temp.pp_id(8))->'facts'->'teams'->'home'->'points'='2','official PDF score');
select pg_temp.pp_assert(public.get_public_game(pg_temp.pp_id(8))->'facts'->'teams'->'home'->'periods'='null','Site total is not quarter');
select pg_temp.pp_assert(public.get_public_game(pg_temp.pp_id(8))->'source'->>'kind'='pdf','source provenance');
select pg_temp.pp_assert((public.get_public_game(pg_temp.pp_id(8))::text)!~'birthDate|birth_date|federation|sourceIndex|sourceSide|sourceMarkers|storage|sha256|sourceId','public whitelist');
select pg_temp.pp_error($q$select public.publish_pdf_game(jsonb_set(pg_temp.pp_revision(),'{source,reviewVersion}','2'))$q$,'PT409');
select pg_temp.pp_error($q$select public.publish_pdf_game(jsonb_set(pg_temp.pp_revision(),'{reason}','""'))$q$,'PT400');
select pg_temp.pp_error($q$select public.publish_pdf_game(jsonb_set(pg_temp.pp_revision(),'{authority,periodScores}','"pdf"'))$q$,'PT400');
select pg_temp.pp_assert(public.publish_pdf_game(pg_temp.pp_revision())->'version'='2','PDF republication');
select pg_temp.pp_assert(jsonb_array_length(public.get_game_publication_state(pg_temp.pp_id(8))->'history')=2,'PDF versions retained');
select pg_temp.pp_error($q$select public.save_pdf_review(jsonb_build_object('commandId',pg_temp.pp_id(410),'sourceId',pg_temp.pp_id(100),'expectedVersion',1,'document',jsonb_set(pg_temp.pp_review(),'{notes}','"changed"')))$q$,'PT400');
select pg_temp.pp_assert(public.save_pdf_review(jsonb_build_object('commandId',pg_temp.pp_id(411),'sourceId',pg_temp.pp_id(100),'expectedVersion',1,'document',jsonb_set(pg_temp.pp_review(),'{notes}','"changed"'),'reason','Revisão com motivo após publicação.'))->'version'='2','review draft can be revised with reason');
select pg_temp.pp_assert(public.get_public_game(pg_temp.pp_id(8))->'version'='2','review save does not republish');
select pg_temp.pp_error($q$select public.save_pdf_review(jsonb_build_object('commandId',pg_temp.pp_id(412),'sourceId',pg_temp.pp_id(100),'expectedVersion',2,'document',jsonb_set(pg_temp.pp_review(),'{gameId}',to_jsonb(pg_temp.pp_id(9))),'reason','Tentativa de trocar destino depois de publicar.'))$q$,'PT409');
reset role;
create function pg_temp.pp_sheet() returns jsonb language sql as $$select jsonb_build_object('rulesVersion','FIBA_2024','periods',4,'participants',(select jsonb_agg(jsonb_build_object('rosterEntryId',v->'rosterEntryId','side',case when v->'sourceSide'='0'::jsonb then 'home' else 'away' end,'jersey',v->'jersey','played',true,'starter',true)) from jsonb_array_elements(pg_temp.pp_review()->'mappings') v),'staff',jsonb_build_object('home',jsonb_build_object('captainRosterEntryId',pg_temp.pp_id(101),'coachStaffEntryId',null,'assistantStaffEntryId',null),'away',jsonb_build_object('captainRosterEntryId',pg_temp.pp_id(106),'coachStaffEntryId',null,'assistantStaffEntryId',null)),'events',jsonb_build_array(jsonb_build_object('id',pg_temp.pp_id(700),'side','home','period',4,'target','0','code','3')))$$;
create function pg_temp.pp_mixed(n integer default 20) returns jsonb language sql as $$select pg_temp.pp_command(n)||jsonb_build_object('gameVersion',3,'basePublicationVersion',2,'source',jsonb_build_object('kind','pdf','sourceId',pg_temp.pp_id(100),'sourceVersion',2,'reviewVersion',2),'authority',jsonb_set(pg_temp.pp_command()->'authority','{scorePoints}','"sheet"'),'sheetVersion',1,'reason','Placar oficial da súmula conferida, avançados do PDF.','acceptDivergence',true)$$;
grant execute on function pg_temp.pp_sheet(),pg_temp.pp_mixed(integer) to authenticated;
set local role authenticated;
select public.save_game_sheet(jsonb_build_object('requestId',pg_temp.pp_id(710),'gameId',pg_temp.pp_id(8),'gameVersion',3,'baseVersion',0,'document',pg_temp.pp_sheet(),'confirm',false,'reason',''));
select pg_temp.pp_error($q$select public.publish_pdf_game(jsonb_set(pg_temp.pp_mixed(),'{acceptDivergence}','false'))$q$,'PT400');
select pg_temp.pp_error($q$select public.publish_pdf_game(jsonb_set(pg_temp.pp_mixed(),'{sheetVersion}','2'))$q$,'PT409');
select pg_temp.pp_assert(public.get_game_sheet(pg_temp.pp_id(8))->'confirmed'='false' and public.get_public_game(pg_temp.pp_id(8))->'version'='2','failed mixed selection preserves prior state');
select pg_temp.pp_assert(public.publish_pdf_game(pg_temp.pp_mixed())->'version'='3','explicit mixed publication');
select pg_temp.pp_assert(public.get_public_game(pg_temp.pp_id(8))->'facts'->'teams'->'home'->'points'='3' and public.get_public_game(pg_temp.pp_id(8))->'facts'->'players'->0->'advanced'->'points'='2','official and advanced points retain independent coverage');
select pg_temp.pp_assert(public.get_game_sheet(pg_temp.pp_id(8))->'confirmed'='true','selected saved manual source is confirmed atomically');
reset role;
select pg_temp.pp_assert(exists(select 1 from private.game_publication_secondary_sources where game_id=pg_temp.pp_id(8) and version=3 and source_kind='sheet' and source_id=pg_temp.pp_id(8) and source_version=1),'secondary source has typed historical reference');
select pg_temp.pp_assert((select document->'manual'->'document'=pg_temp.pp_sheet() from private.game_publication_versions where game_id=pg_temp.pp_id(8) and version=3),'raw manual source frozen alongside mixed publication');
set local role anon;
select pg_temp.pp_assert(public.get_public_game(pg_temp.pp_id(8)) is not null and public.get_public_game(pg_temp.pp_id(9)) is null,'only selected game published');
select pg_temp.pp_error('select * from private.game_publication_versions','42501');
reset role;
update public.admin_access set enabled=false where user_id=pg_temp.pp_id(98);
set local role authenticated;
select pg_temp.pp_error('select public.publish_pdf_game(pg_temp.pp_command())','PT403');
reset role;
rollback;
